    index?: string;
    account_root?: string;
    check?: string;
    credential?: {
        subject: string;
        issuer: string;
        credentialType: string;
    } | string;
    deposit_preauth?: {
        owner: string;
        authorized: string;
    } | string;
    did?: string;
    directory?: {
        sub_index?: number;
        dir_root?: string;
        owner?: string;
    } | string;
    escrow?: {
        owner: string;
        seq: number;
    } | string;
    offer?: {
        account: string;
        seq: number;
    } | string;
    payment_channel?: string;
    ripple_state?: {
        accounts: string[];
        currency: string;
    };
    ticket?: {
        owner: string;
        ticket_sequence: number;
    } | string;
    nft_page?: string;
    bridge_account?: string;
    bridge?: XChainBridge;
    xchain_owned_claim_id?: {
        locking_chain_door: string;
        locking_chain_issue: Currency;
        issuing_chain_door: string;
        issuing_chain_issue: Currency;
        xchain_owned_claim_id: string | number;
    } | string;
