const { Client, Wallet } = require('xrpl');

const TESTNET_URL = 'wss://s.altnet.rippletest.net:51233';
const ISSUER_SEED = '<TESTNET_SEED_REDACTED>';
const ISSUANCE_ID = '01427D3B2EC7F1F7FCFED0B4396BF2AEAD753F5EA7E0C412';

async function submit(client, tx, wallet) {
  const resp = await client.submitAndWait(tx, { wallet });
  const result = resp.result.meta && typeof resp.result.meta === 'object' ? resp.result.meta.TransactionResult : undefined;
  console.log(`${tx.TransactionType} by ${wallet.address} -> ${result}`);
  return resp;
}

async function main() {
  const client = new Client(TESTNET_URL);
  await client.connect();
  const issuer = Wallet.fromSeed(ISSUER_SEED);
  const x = Wallet.generate();
  const y = Wallet.generate();
  console.log('X', x.address);
  console.log('Y', y.address);

  await submit(client, { TransactionType: 'Payment', Account: issuer.address, Destination: x.address, Amount: '15000000' }, issuer);
  await submit(client, { TransactionType: 'Payment', Account: issuer.address, Destination: y.address, Amount: '15000000' }, issuer);

  await submit(client, { TransactionType: 'MPTokenAuthorize', Account: x.address, MPTokenIssuanceID: ISSUANCE_ID }, x);
  await submit(client, { TransactionType: 'MPTokenAuthorize', Account: y.address, MPTokenIssuanceID: ISSUANCE_ID }, y);
  await submit(client, { TransactionType: 'MPTokenAuthorize', Account: issuer.address, MPTokenIssuanceID: ISSUANCE_ID, Holder: x.address }, issuer);
  await submit(client, { TransactionType: 'MPTokenAuthorize', Account: issuer.address, MPTokenIssuanceID: ISSUANCE_ID, Holder: y.address }, issuer);

  await submit(client, { TransactionType: 'Payment', Account: issuer.address, Destination: x.address, Amount: { mpt_issuance_id: ISSUANCE_ID, value: '100' } }, issuer);

  console.log('--- locking X ---');
  await submit(client, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.address, MPTokenIssuanceID: ISSUANCE_ID, Holder: x.address, Flags: { tfMPTLock: true } }, issuer);

  console.log('--- X (locked) attempts to pay Y ---');
  await submit(client, { TransactionType: 'Payment', Account: x.address, Destination: y.address, Amount: { mpt_issuance_id: ISSUANCE_ID, value: '10' } }, x);

  console.log('--- issuer attempts to pay X (locked) again ---');
  await submit(client, { TransactionType: 'Payment', Account: issuer.address, Destination: x.address, Amount: { mpt_issuance_id: ISSUANCE_ID, value: '5' } }, issuer);

  console.log('--- issuer claws back from locked X ---');
  await submit(client, { TransactionType: 'Clawback', Account: issuer.address, Holder: x.address, Amount: { mpt_issuance_id: ISSUANCE_ID, value: '1' } }, issuer);

  await client.disconnect();
}

main().catch((e) => { console.error(e); process.exit(1); });

