  MPTokenAuthorize,
  MPTokenIssuanceSet,
  Clawback,
  Payment,
  SubmittableTransaction,
  TxResponse,
  MPTokenMetadata,
  LedgerEntry,
} from 'xrpl';
import { MptIssuerError } from './errors';

/**
 * MPToken (holder-level) ledger entry flags. These are defined by the
 * XLS-33d amendment but xrpl.js does not export a named enum for them
